package com.persiawar2d;

import android.content.Context;
import android.graphics.*;
import android.graphics.drawable.Drawable;
import java.util.*;

/** 2.5D world renderer using the existing Kenney isometric pack for houses, roads, trees and vegetation. */
public final class WorldRenderer {
 public static final float WORLD_SIZE=6000f;
 private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);
 private final Drawable background,ground; private final KenneyEnvironment kenney=new KenneyEnvironment();
 private final ArrayList<Building> buildings=new ArrayList<>(); private final ArrayList<Shrub> shrubs=new ArrayList<>(); private final ArrayList<Road> roads=new ArrayList<>(); private final Random random=new Random(20260816L);
 public WorldRenderer(Context c){background=c.getDrawable(R.drawable.achaemenid_background);ground=c.getDrawable(R.drawable.persia_ground);kenney.load(c);buildLayout();}
 private void buildLayout(){
  roads.add(new Road(300,980,5700,980,150));roads.add(new Road(420,2850,5600,2850,125));roads.add(new Road(700,4650,5300,4650,140));roads.add(new Road(1200,300,1200,5700,130));roads.add(new Road(3380,250,3380,5750,150));roads.add(new Road(5050,600,5050,5400,120));roads.add(new Road(600,1600,2300,1600,70));roads.add(new Road(1900,1100,1900,2700,62));roads.add(new Road(2580,2950,2580,4500,64));roads.add(new Road(3650,1650,4900,1650,68));roads.add(new Road(4200,3150,4200,5050,70));roads.add(new Road(850,3900,2500,3900,66));roads.add(new Road(4700,900,4700,2500,60));
  int[][] spots={{430,520,360,280},{1530,520,430,300},{2250,520,470,320},{3900,520,500,330},{4550,620,380,260},{5400,580,330,350},{520,2050,420,320},{1500,2050,500,340},{2200,1900,380,280},{3600,2050,520,320},{4450,2100,420,310},{5200,1900,430,330},{500,3350,450,310},{1500,3250,420,300},{2850,3500,520,340},{3650,3500,450,290},{4700,3550,520,330},{5200,4200,390,300},{650,5000,500,300},{1750,5000,430,330},{2900,5000,460,310},{3850,5100,500,300},{4750,5100,420,330}};
  int i=0;for(int[] s:spots){buildings.add(new Building(s[0],s[1],s[2],s[3],i%12));if(i%3!=1)buildings.add(new Building(s[0]+s[2]+90,s[1]+35,210+(i%3)*55,190+(i%4)*30,(i+3)%12));i++;}
  for(int n=0;n<110;n++){float x=260+random.nextFloat()*5480,y=300+random.nextFloat()*5400;if(!nearRoad(x,y,95))shrubs.add(new Shrub(x,y,18+random.nextFloat()*22,n));}
 }
 private boolean nearRoad(float x,float y,float pad){for(Road r:roads){if(r.x1==r.x2&&Math.abs(x-r.x1)<r.w/2+pad&&y>=Math.min(r.y1,r.y2)-pad&&y<=Math.max(r.y1,r.y2)+pad)return true;if(r.y1==r.y2&&Math.abs(y-r.y1)<r.w/2+pad&&x>=Math.min(r.x1,r.x2)-pad&&x<=Math.max(r.x1,r.x2)+pad)return true;}return false;}
 public void draw(Canvas c,float px,float py,float s,float vw,float vh,float hud){drawParallaxBackground(c,px,py,vw,vh,hud);p.setColor(Color.rgb(38,58,47));c.drawRect(0,hud,vw,vh,p);float ox=vw/2f-px*s,oy=(vh+hud)/2f-py*s;c.save();c.translate(ox,oy);drawGround(c,s);drawRoads(c,s);for(Shrub sh:shrubs)if(sh.y<=py+20)drawShrub(c,sh,s);for(Building b:buildings)if(b.y<=py+20)drawBuilding(c,b,s);c.restore();}
 public void drawForeground(Canvas c,float px,float py,float s){float ox=getLastViewW()/2f-px*s,oy=(getLastViewH()+getLastHud())/2f-py*s;c.save();c.translate(ox,oy);for(Shrub sh:shrubs)if(sh.y>py+20)drawShrub(c,sh,s);for(Building b:buildings)if(b.y>py+20)drawBuilding(c,b,s);c.restore();}
 private float lastW,lastH,lastHud; private float getLastViewW(){return lastW;} private float getLastViewH(){return lastH;} private float getLastHud(){return lastHud;}
 private void drawParallaxBackground(Canvas c,float px,float py,float vw,float vh,float hud){lastW=vw;lastH=vh;lastHud=hud;p.setColor(Color.rgb(24,39,35));c.drawRect(0,hud,vw,vh,p);if(background==null)return;float x=-(px*.055f)%vw,y=-(py*.035f)%Math.max(1,vh-hud);int top=Math.round(hud),w=Math.round(vw*1.18f),h=Math.max(Math.round(vh-hud),Math.round((vh-hud)*.72f));background.setAlpha(235);background.setBounds(Math.round(x-w*.09f),top+Math.round(y*.2f),Math.round(x+w),top+h+Math.round(y*.2f));background.draw(c);background.setBounds(Math.round(x+w*.82f),top+Math.round(y*.2f),Math.round(x+w*1.91f),top+h+Math.round(y*.2f));background.draw(c);background.setAlpha(255);}
 private void drawGround(Canvas c,float s){p.setColor(Color.rgb(112,105,78));c.drawRect(0,0,WORLD_SIZE*s,WORLD_SIZE*s,p);if(ground!=null){int tile=Math.max(256,(int)(520*s));for(int y=0;y<WORLD_SIZE*s;y+=tile)for(int x=0;x<WORLD_SIZE*s;x+=tile){ground.setBounds(x,y,x+tile,y+tile);ground.setAlpha(90);ground.draw(c);}}Bitmap grass=kenney.grass(0);if(grass!=null){int tile=Math.max(220,(int)(420*s));for(int y=0;y<WORLD_SIZE*s;y+=tile)for(int x=0;x<WORLD_SIZE*s;x+=tile){c.drawBitmap(grass,null,new RectF(x,y,x+tile,y+tile),p);}}}
 private void drawRoads(Canvas c,float s){for(int i=0;i<roads.size();i++){Road r=roads.get(i);Bitmap art=kenney.road(i);if(art!=null){float x1=Math.min(r.x1,r.x2)*s,y1=Math.min(r.y1,r.y2)*s,x2=Math.max(r.x1,r.x2)*s,y2=Math.max(r.y1,r.y2)*s;if(r.x1==r.x2){for(float y=y1;y<y2;y+=r.w*s)c.drawBitmap(art,null,new RectF((r.x1-r.w/2)*s,y,(r.x1+r.w/2)*s,Math.min(y+r.w*s,y2)),p);}else{for(float x=x1;x<x2;x+=r.w*s)c.drawBitmap(art,null,new RectF(x,(r.y1-r.w/2)*s,Math.min(x+r.w*s,x2),(r.y1+r.w/2)*s),p);}}else{p.setColor(Color.rgb(73,69,57));if(r.x1==r.x2)c.drawRect((r.x1-r.w/2)*s,Math.min(r.y1,r.y2)*s,(r.x1+r.w/2)*s,Math.max(r.y1,r.y2)*s,p);else c.drawRect(Math.min(r.x1,r.x2)*s,(r.y1-r.w/2)*s,Math.max(r.x1,r.x2)*s,(r.y1+r.w/2)*s,p);}}}
 private void drawBuilding(Canvas c,Building b,float s){Bitmap art=kenney.building(b.kind);float x=b.x*s,y=b.y*s,depth=.78f+(b.y/WORLD_SIZE)*.42f;float w=b.w*s,h=b.h*s*.75f*depth;if(art!=null){float ratio=art.getHeight()/(float)Math.max(1,art.getWidth());h=w*ratio*.78f;c.drawBitmap(art,null,new RectF(x,y-h,x+w,y),p);}else{p.setColor(Color.rgb(157,123,82));c.drawRect(x,y-h,x+w,y,p);}}
 private void drawShrub(Canvas c,Shrub sh,float s){Bitmap art=(sh.index%3==0)?kenney.tree(sh.index):kenney.grass(sh.index);float x=sh.x*s,y=sh.y*s,depth=.78f+(sh.y/WORLD_SIZE)*.42f,size=sh.r*7f*s*depth;if(art!=null){float ratio=art.getHeight()/(float)Math.max(1,art.getWidth());c.drawBitmap(art,null,new RectF(x-size*.5f,y-size*ratio,x+size*.5f,y),p);}else{p.setColor(Color.rgb(49,94,53));c.drawCircle(x,y,sh.r*s,p);}}
 static final class Building{final float x,y,w,h;final int kind;Building(float x,float y,float w,float h,int kind){this.x=x;this.y=y;this.w=w;this.h=h;this.kind=kind;}}
 static final class Shrub{final float x,y,r;final int index;Shrub(float x,float y,float r,int index){this.x=x;this.y=y;this.r=r;this.index=index;}}
 static final class Road{final float x1,y1,x2,y2,w;Road(float x1,float y1,float x2,float y2,float w){this.x1=x1;this.y1=y1;this.x2=x2;this.y2=y2;this.w=w;}}
}
